import json, csv, pandas as pd

FIELD_MAP = {
    'user_id': 'user_id', 'id': 'user_id', 'userId': 'user_id',
    'email': 'email', 'email_address': 'email',
    'full_name': 'name', 'name': 'name', 'userName': 'name',
    'registration_date': 'created_date', 'created_at': 'created_date', 'joined': 'created_date',
    'status': 'status', 'is_active': 'status', 'active': 'status',
}

FIELDS = ['name', 'email', 'created_date', 'status']


def norm_status(v):
    if isinstance(v, bool):
        return 'active' if v else 'inactive'
    s = str(v).strip().lower()
    if s in ('true', '1'):
        return 'active'
    if s in ('false', '0'):
        return 'inactive'
    return str(v)


def norm_date(v):
    if v is None:
        return None
    return pd.to_datetime(str(v)).strftime('%Y-%m-%d')


def map_record(raw):
    rec = {}
    for k, v in raw.items():
        if k not in FIELD_MAP:
            continue
        uk = FIELD_MAP[k]
        if v is None or (isinstance(v, float) and pd.isna(v)):
            continue
        if uk == 'user_id':
            rec[uk] = int(v)
        elif uk == 'created_date':
            rec[uk] = norm_date(v)
        elif uk == 'status':
            rec[uk] = norm_status(v)
        else:
            rec[uk] = str(v)
    return rec


# source_a
with open('/data/source_a/users.json') as f:
    a = [map_record(r) for r in json.load(f)]

# source_b
b = []
with open('/data/source_b/users.csv', newline='') as f:
    for r in csv.DictReader(f):
        b.append(map_record(r))

# source_c
cdf = pd.read_parquet('/data/source_c/users.parquet')
c = [map_record(r) for r in cdf.to_dict('records')]

sources = {'source_a': a, 'source_b': b, 'source_c': c}
PRIORITY = ['source_a', 'source_b', 'source_c']

# index by user_id
by_user = {}
for sname in PRIORITY:
    for rec in sources[sname]:
        uid = rec['user_id']
        by_user.setdefault(uid, {})[sname] = rec

merged = []
conflicts = []
for uid in sorted(by_user):
    srecs = by_user[uid]
    out = {'user_id': uid}
    for field in FIELDS:
        values = {}
        for sname in PRIORITY:
            if sname in srecs and field in srecs[sname]:
                values[sname] = srecs[sname][field]
        if not values:
            out[field] = None
            continue
        selected = values[next(iter([s for s in PRIORITY if s in values]))]
        out[field] = selected
        if len(set(values.values())) > 1:
            conflicts.append({
                'user_id': uid,
                'field': field,
                'values': values,
                'selected': selected,
            })
    merged.append(out)

mdf = pd.DataFrame(merged, columns=['user_id', 'name', 'email', 'created_date', 'status'])
mdf['user_id'] = mdf['user_id'].astype('int64')
for col in ['name', 'email', 'created_date', 'status']:
    mdf[col] = mdf[col].astype('object')
mdf.to_parquet('/app/merged_users.parquet', index=False)

report = {'total_conflicts': len(conflicts), 'conflicts': conflicts}
with open('/app/conflicts.json', 'w') as f:
    json.dump(report, f, indent=2)

print(mdf)
print(json.dumps(report, indent=2))

